package main

// Single TLS port with ALPN multiplexing (ADR 0006 option A):
//   - ALPN "uc-raft/1" -> hashicorp/raft NetworkTransport via a StreamLayer
//   - ALPN "h2"        -> net/http (HTTP/2) for forwarding, join and replication
// Both directions use mTLS against a spike CA generated by `spike pki`.

import (
	"crypto/ecdsa"
	"crypto/elliptic"
	"crypto/rand"
	"crypto/tls"
	"crypto/x509"
	"crypto/x509/pkix"
	"encoding/pem"
	"errors"
	"fmt"
	"log/slog"
	"math/big"
	"net"
	"net/http"
	"os"
	"path/filepath"
	"time"

	"github.com/hashicorp/raft"
)

const alpnRaft = "uc-raft/1"

// genPKI writes ca.pem and <name>.pem/<name>-key.pem for every name.
func genPKI(dir string, names []string) error {
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return err
	}
	caKey, err := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
	if err != nil {
		return err
	}
	caTmpl := &x509.Certificate{
		SerialNumber:          big.NewInt(1),
		Subject:               pkix.Name{CommonName: "uptimecluster spike CA"},
		NotBefore:             time.Now().Add(-5 * time.Minute),
		NotAfter:              time.Now().Add(30 * 24 * time.Hour),
		IsCA:                  true,
		BasicConstraintsValid: true,
		KeyUsage:              x509.KeyUsageCertSign | x509.KeyUsageDigitalSignature,
	}
	caDER, err := x509.CreateCertificate(rand.Reader, caTmpl, caTmpl, &caKey.PublicKey, caKey)
	if err != nil {
		return err
	}
	caCert, _ := x509.ParseCertificate(caDER)
	if err := writePEM(filepath.Join(dir, "ca.pem"), "CERTIFICATE", caDER); err != nil {
		return err
	}
	for i, name := range names {
		key, err := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
		if err != nil {
			return err
		}
		tmpl := &x509.Certificate{
			SerialNumber: big.NewInt(int64(i + 2)),
			Subject:      pkix.Name{CommonName: name},
			DNSNames:     []string{name, "raft-" + name, "localhost"},
			IPAddresses:  []net.IP{net.ParseIP("127.0.0.1")},
			NotBefore:    time.Now().Add(-5 * time.Minute),
			NotAfter:     time.Now().Add(30 * 24 * time.Hour),
			KeyUsage:     x509.KeyUsageDigitalSignature,
			ExtKeyUsage:  []x509.ExtKeyUsage{x509.ExtKeyUsageServerAuth, x509.ExtKeyUsageClientAuth},
		}
		der, err := x509.CreateCertificate(rand.Reader, tmpl, caCert, &key.PublicKey, caKey)
		if err != nil {
			return err
		}
		keyDER, err := x509.MarshalECPrivateKey(key)
		if err != nil {
			return err
		}
		if err := writePEM(filepath.Join(dir, name+".pem"), "CERTIFICATE", der); err != nil {
			return err
		}
		if err := writePEM(filepath.Join(dir, name+"-key.pem"), "EC PRIVATE KEY", keyDER); err != nil {
			return err
		}
	}
	return nil
}

func writePEM(path, typ string, der []byte) error {
	return os.WriteFile(path, pem.EncodeToMemory(&pem.Block{Type: typ, Bytes: der}), 0o644)
}

type tlsMaterial struct {
	cert tls.Certificate
	pool *x509.CertPool
}

func loadTLS(dir, name string) (*tlsMaterial, error) {
	cert, err := tls.LoadX509KeyPair(filepath.Join(dir, name+".pem"), filepath.Join(dir, name+"-key.pem"))
	if err != nil {
		return nil, fmt.Errorf("load leaf: %w", err)
	}
	caPEM, err := os.ReadFile(filepath.Join(dir, "ca.pem"))
	if err != nil {
		return nil, fmt.Errorf("load ca: %w", err)
	}
	pool := x509.NewCertPool()
	if !pool.AppendCertsFromPEM(caPEM) {
		return nil, errors.New("invalid ca.pem")
	}
	return &tlsMaterial{cert: cert, pool: pool}, nil
}

func (m *tlsMaterial) serverConfig() *tls.Config {
	return &tls.Config{
		Certificates: []tls.Certificate{m.cert},
		ClientCAs:    m.pool,
		ClientAuth:   tls.RequireAndVerifyClientCert,
		NextProtos:   []string{alpnRaft, "h2"},
		MinVersion:   tls.VersionTLS13,
	}
}

func (m *tlsMaterial) clientConfig(proto string) *tls.Config {
	return &tls.Config{
		Certificates: []tls.Certificate{m.cert},
		RootCAs:      m.pool,
		NextProtos:   []string{proto},
		MinVersion:   tls.VersionTLS13,
	}
}

// mux accepts TLS connections on one port and dispatches by ALPN.
type mux struct {
	ln       net.Listener
	tlsm     *tlsMaterial
	advAddr  string
	raftConn chan net.Conn
	httpConn chan net.Conn
	closed   chan struct{}
}

func newMux(listen, advertise string, tlsm *tlsMaterial) (*mux, error) {
	ln, err := net.Listen("tcp", listen)
	if err != nil {
		return nil, err
	}
	m := &mux{
		ln: ln, tlsm: tlsm, advAddr: advertise,
		raftConn: make(chan net.Conn, 16),
		httpConn: make(chan net.Conn, 16),
		closed:   make(chan struct{}),
	}
	go m.acceptLoop()
	return m, nil
}

func (m *mux) acceptLoop() {
	cfg := m.tlsm.serverConfig()
	for {
		c, err := m.ln.Accept()
		if err != nil {
			select {
			case <-m.closed:
				return
			default:
			}
			slog.Warn("mux accept", "err", err)
			time.Sleep(50 * time.Millisecond)
			continue
		}
		go func() {
			tc := tls.Server(c, cfg)
			_ = tc.SetDeadline(time.Now().Add(5 * time.Second))
			if err := tc.Handshake(); err != nil {
				slog.Debug("tls handshake failed", "remote", c.RemoteAddr(), "err", err)
				_ = c.Close()
				return
			}
			_ = tc.SetDeadline(time.Time{})
			switch tc.ConnectionState().NegotiatedProtocol {
			case alpnRaft:
				m.raftConn <- tc
			case "h2":
				m.httpConn <- tc // must stay *tls.Conn so net/http picks the h2 handler
			default:
				_ = tc.Close()
			}
		}()
	}
}

func (m *mux) Close() error {
	close(m.closed)
	return m.ln.Close()
}

// chanListener exposes one ALPN lane as a net.Listener.
type chanListener struct {
	ch   chan net.Conn
	addr net.Addr
	done chan struct{}
}

func (l *chanListener) Accept() (net.Conn, error) {
	select {
	case c := <-l.ch:
		return c, nil
	case <-l.done:
		return nil, net.ErrClosed
	}
}
func (l *chanListener) Close() error   { return nil }
func (l *chanListener) Addr() net.Addr { return l.addr }

// raftLayer implements raft.StreamLayer on top of the mux.
type raftLayer struct {
	chanListener
	m *mux
}

func (m *mux) raftLayer() *raftLayer {
	return &raftLayer{
		chanListener: chanListener{ch: m.raftConn, addr: advAddr(m.advAddr), done: m.closed},
		m:            m,
	}
}

func (l *raftLayer) Dial(address raft.ServerAddress, timeout time.Duration) (net.Conn, error) {
	d := &net.Dialer{Timeout: timeout}
	cfg := l.m.tlsm.clientConfig(alpnRaft)
	host, _, _ := net.SplitHostPort(string(address))
	cfg.ServerName = host
	return tls.DialWithDialer(d, "tcp", string(address), cfg)
}

func (m *mux) httpListener() net.Listener {
	return &chanListener{ch: m.httpConn, addr: m.ln.Addr(), done: m.closed}
}

// httpClient talks HTTP/2 over mTLS to peers.
func (m *mux) httpClient() *http.Client {
	tr := &http.Transport{
		TLSClientConfig:     m.tlsm.clientConfig("h2"),
		ForceAttemptHTTP2:   true,
		TLSHandshakeTimeout: 3 * time.Second,
		IdleConnTimeout:     30 * time.Second,
		// Without pings a half-open h2 connection (network partition) is only
		// noticed via the request timeout.
		HTTP2: &http.HTTP2Config{SendPingTimeout: 5 * time.Second, PingTimeout: 3 * time.Second},
	}
	return &http.Client{Transport: tr, Timeout: 10 * time.Second}
}

type advAddr string

func (a advAddr) Network() string { return "tcp" }
func (a advAddr) String() string  { return string(a) }
